  right+=f'<article class="mini-world {"failed" if bad else ""} {"selected" if name=="S4" else ""}" aria-label="{name}: {reason}. {"Failed" if bad else "Passed"}"><div class="mini-picture">{scene(bad,True,i,prefix)}</div><div class="mini-caption"><span>{name}</span><span class="{"fail" if bad else "pass"}">{"Fail" if bad else "Pass"}</span></div></article>'
